/*
 * A209567  Triangle of coefficients of polynomials u(n,x) jointly generated
 *          with A209568; see the Formula section.
 * https://oeis.org/A209567
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) is 1 at triangular indices, otherwise it is a coefficient
 *            of the polynomial u(r+1,x) where r satisfies n ≤ r(r+3)/2 and p
 *            = n – r(r+1)/2, 0 ≤ p ≤ r. For p > 0 a(n) = u(r+1)[p‑1]. The
 *            polynomials u and v are generated by u(1,x)=1, v(1,x)=1
 *            u(n,x)=x*u(n‑1,x)+v(n‑1,x) v(n,x)=x*u(n‑1,x)+(x+1)*v(...
 * Range:     u8 n <= 39, u16 n <= 63, u32 n <= 63, u64 n <= 63, u128 n <= 63,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>

static seq_t **u_coeff = NULL;   /* u_coeff[k] points to array of length k
                                    containing coefficients of u(k,x) */
static seq_t **v_coeff = NULL;
static idx_t max_k_prepared = 0; /* highest k for which u_coeff and v_coeff are filled */

/* Create u(k,x) and v(k,x) for all k up to k_needed. */
static void prepare_u_v(idx_t k_needed)
{
    if (k_needed <= max_k_prepared)
        return;                    /* nothing to do */

    /* Grow the pointer tables */
    idx_t new_size = k_needed + 1;   /* indices 0..k_needed (we ignore index 0) */
    u_coeff = (seq_t **)realloc(u_coeff, new_size * sizeof(seq_t *));
    v_coeff = (seq_t **)realloc(v_coeff, new_size * sizeof(seq_t *));

    /* Base case: u(1) and v(1) */
    if (max_k_prepared == 0) {
        u_coeff[1] = (seq_t *)malloc(sizeof(seq_t));
        u_coeff[1][0] = (seq_t)1;
        v_coeff[1] = (seq_t *)malloc(sizeof(seq_t));
        v_coeff[1][0] = (seq_t)1;
        max_k_prepared = 1;
    }

    /* Build u(k) and v(k) for k = max_k_prepared+1 .. k_needed */
    for (idx_t k = max_k_prepared + 1; k <= k_needed; ++k) {
        idx_t prev_len = k - 1;                /* length of u(k-1) and v(k-1) */
        seq_t *u_prev = u_coeff[k - 1];
        seq_t *v_prev = v_coeff[k - 1];

        seq_t *u_cur = (seq_t *)malloc(sizeof(seq_t) * k);
        seq_t *v_cur = (seq_t *)malloc(sizeof(seq_t) * k);

        /* u(k) = x*u(k-1) + v(k-1) */
        /* constant term */
        u_cur[0] = v_prev[0];
        /* middle terms */
        for (idx_t i = 1; i < k - 1; ++i) {
            u_cur[i] = u_prev[i - 1] + v_prev[i];
        }
        /* highest term */
        u_cur[k - 1] = u_prev[k - 2];

        /* v(k) = x*u(k-1) + (x+1)*v(k-1) + 1 */
        /* start with zeroes */
        for (idx_t i = 0; i < k; ++i)
            v_cur[i] = (seq_t)0;
        /* contributions from x*u(k-1) and (x+1)*v(k-1) */
        for (idx_t i = 0; i < k - 1; ++i) {
            v_cur[i + 1] += u_prev[i];
            v_cur[i]     += v_prev[i];
            v_cur[i + 1] += v_prev[i];
        }
        /* constant addition */
        v_cur[0] += (seq_t)1;

        u_coeff[k] = u_cur;
        v_coeff[k] = v_cur;
    }

    max_k_prepared = k_needed;
}

/* Main sequence function */
seq_t a(idx_t n)
{
    /* Find row r such that n ≤ r(r+3)/2, i.e. n lies in row r */
    idx_t r = 1;
    while (n > r * (r + 3) / 2)
        ++r;

    /* Start index of row r */
    idx_t start = r * (r + 1) / 2;
    idx_t offset = n - start;            /* 0 … r */

    if (offset == 0)
        return (seq_t)1;                 /* the moved last coefficient */

    /* Ensure we have computed u(r+1) */
    prepare_u_v(r + 1);

    return u_coeff[r + 1][offset - 1];
}
